/* Strict hidden rule constraint */
[hidden] {
  display: none !important;
}

:root {
  --bg-dark: #1f1b2c;
  --machine-body: #3c3453;
  --machine-accent: #6b5c8f;
  --panel-bg: #12101a;
  --screen-green: #5af78e;
  --screen-bg: #091a10;
  --accent-yellow: #f1fa8c;
  --accent-red: #ff5555;
  --text-main: #f8f8f2;
  --border-dark: #12101a;
  --font-family: 'Courier New', Courier, monospace, system-ui;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-family);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

/* Main Cabinet */
.machine-container {
  background-color: var(--machine-body);
  border: 4px solid var(--border-dark);
  box-shadow:
    inset 4px 4px 0 #584c7a,
    inset -4px -4px 0 #282238,
    8px 8px 0 rgba(0, 0, 0, 0.4);
  width: 100%;
  max-width: 440px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.machine-header {
  text-align: center;
  border-bottom: 3px solid var(--border-dark);
  padding-bottom: 12px;
}

.machine-title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  color: var(--accent-yellow);
  text-shadow: 2px 2px 0 var(--border-dark);
}

.machine-subtitle {
  font-size: 0.85rem;
  color: var(--text-main);
  margin-top: 4px;
  opacity: 0.9;
}

/* Snack Showcase */
.showcase {
  background-color: var(--panel-bg);
  border: 4px solid var(--border-dark);
  padding: 12px;
  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.8);
}

.snack-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.snack-card {
  background-color: var(--machine-accent);
  border: 3px solid var(--border-dark);
  color: var(--text-main);
  padding: 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  font-family: inherit;
  font-size: 0.9rem;
  position: relative;
  transition: transform 0.08s ease, background-color 0.1s ease;
  outline: none;
}

.snack-card:hover {
  background-color: #7b6ba3;
  transform: translateY(-2px);
}

.snack-card:focus-visible {
  border-color: var(--accent-yellow);
  box-shadow: 0 0 0 3px var(--accent-yellow);
}

.snack-card:active {
  transform: translateY(2px);
  background-color: #554873;
}

.code-tag {
  position: absolute;
  top: 4px;
  left: 4px;
  font-size: 0.75rem;
  background: var(--border-dark);
  padding: 1px 4px;
  border-radius: 2px;
}

.pixel-art {
  image-rendering: pixelated;
  margin: 6px 0;
  background: rgba(0, 0, 0, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.snack-name {
  font-weight: bold;
  margin-bottom: 2px;
  text-align: center;
}

.snack-price {
  font-size: 0.85rem;
  color: var(--accent-yellow);
}

/* Control Panel */
.control-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.display-screen {
  background-color: var(--screen-bg);
  border: 3px solid var(--border-dark);
  padding: 10px;
  color: var(--screen-green);
  box-shadow: inset 0 0 8px rgba(0, 0, 0, 0.7);
}

.credit-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 1.1rem;
  font-weight: bold;
}

.status-message {
  margin-top: 6px;
  font-size: 0.95rem;
  min-height: 1.4em;
  word-break: break-word;
}

.status-message.error {
  color: var(--accent-red);
}

.coin-controls {
  background: rgba(0, 0, 0, 0.15);
  padding: 8px;
  border: 2px solid var(--border-dark);
}

.section-label {
  font-size: 0.8rem;
  color: var(--accent-yellow);
  margin-bottom: 6px;
  text-align: center;
  letter-spacing: 1px;
}

.button-row {
  display: flex;
  gap: 8px;
}

.pixel-btn {
  flex: 1;
  background-color: var(--machine-accent);
  color: var(--text-main);
  border: 3px solid var(--border-dark);
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: bold;
  padding: 10px 6px;
  cursor: pointer;
  outline: none;
  transition: transform 0.08s ease, background-color 0.1s ease;
}

.pixel-btn:hover {
  background-color: #7b6ba3;
}

.pixel-btn:focus-visible {
  border-color: var(--accent-yellow);
  box-shadow: 0 0 0 3px var(--accent-yellow);
}

.pixel-btn:active {
  transform: translateY(2px);
  background-color: #554873;
}

/* Dispense Tray */
.delivery-tray {
  background-color: var(--panel-bg);
  border: 3px solid var(--border-dark);
  padding: 8px;
  text-align: center;
}

.tray-label {
  font-size: 0.75rem;
  color: #888;
  letter-spacing: 2px;
  display: block;
  margin-bottom: 4px;
}

.tray-slot {
  background-color: #000;
  border: 2px solid var(--border-dark);
  padding: 10px;
  min-height: 38px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.tray-contents {
  font-size: 0.9rem;
  color: var(--accent-yellow);
}

/* Responsive adjustments */
@media (max-width: 380px) {
  .machine-container {
    padding: 14px;
  }
  .snack-card {
    font-size: 0.8rem;
    padding: 6px;
  }
  .pixel-btn {
    font-size: 0.85rem;
    padding: 8px 4px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // State stored in integer cents to avoid floating point inaccuracies
  let creditCents = 0;

  const snacks = [
    { id: '1', code: 'A1', name: 'Pixel Cola', priceCents: 125, type: 'soda' },
    { id: '2', code: 'A2', name: 'Cyber Chips', priceCents: 150, type: 'chips' },
    { id: '3', code: 'B1', name: 'Bit Candy', priceCents: 75, type: 'candy' },
    { id: '4', code: 'B2', name: 'Retro Choc', priceCents: 200, type: 'choc' }
  ];

  // Elements
  const creditDisplay = document.getElementById('creditDisplay');
  const statusMsg = document.getElementById('statusMsg');
  const btnInsert25 = document.getElementById('btnInsert25');
  const btnInsert100 = document.getElementById('btnInsert100');
  const trayText = document.getElementById('trayText');
  const snackButtons = document.querySelectorAll('.snack-card');

  function formatCurrency(cents) {
    return '$' + (cents / 100).toFixed(2);
  }

  function updateCreditDisplay() {
    creditDisplay.textContent = formatCurrency(creditCents);
  }

  function setStatus(message, isError = false) {
    statusMsg.textContent = message;
    if (isError) {
      statusMsg.classList.add('error');
    } else {
      statusMsg.classList.remove('error');
    }
  }

  function addCredit(cents) {
    creditCents += cents;
    updateCreditDisplay();
    setStatus(`Inserted ${formatCurrency(cents)}. Select a snack.`);
  }

  function handleSnackSelect(snackId) {
    const snack = snacks.find(s => s.id === snackId);
    if (!snack) return;

    if (creditCents >= snack.priceCents) {
      const changeCents = creditCents - snack.priceCents;
      creditCents = 0;
      updateCreditDisplay();

      const changeStr = formatCurrency(changeCents);
      setStatus(`Dispensed ${snack.name}! Change: ${changeStr}`);
      trayText.textContent = `${snack.name} + ${changeStr} Change`;
    } else {
      setStatus('Not enough credit', true);
    }
  }

  // Event Listeners
  btnInsert25.addEventListener('click', () => addCredit(25));
  btnInsert100.addEventListener('click', () => addCredit(100));

  snackButtons.forEach(button => {
    button.addEventListener('click', () => {
      const snackId = button.getAttribute('data-id');
      handleSnackSelect(snackId);
    });
  });

  // Draw 8x8 pixel art snacks onto canvases
  function renderPixelArt() {
    const canvases = document.querySelectorAll('canvas.pixel-art');
    const colorMap = {
      '.': 'transparent',
      'R': '#ff5555',
      'D': '#bd2e2e',
      'Y': '#f1fa8c',
      'O': '#ffb86c',
      'B': '#8be9fd',
      'W': '#f8f8f2',
      'C': '#6f42c1',
      'M': '#693e1b'
    };

    const sprites = {
      soda: [
        '..WW....',
        '.RDRD...',
        '.RDRD...',
        '.RWWD...',
        '.RDRD...',
        '.RDRD...',
        '.RDRD...',
        '..DD....'
      ],
      chips: [
        '..YYYY..',
        '.YYYYYY.',
        '.YOOOOY.',
        '.YOOOOY.',
        '.YOOOOY.',
        '.YYYYYY.',
        '..YYYY..',
        '........'
      ],
      candy: [
        '........',
        '.W....W.',
        '..BWWWB..',
        '..BCWCB..',
        '..BCWCB..',
        '..BWWWB..',
        '.W....W.',
        '........'
      ],
      choc: [
        '..MMMM..',
        '.MMMMMM.',
        '.MM.MM..',
        '.MMMMMM.',
        '.MM.MM..',
        '.MMMMMM.',
        '.MMMMMM.',
        '..MMMM..'
      ]
    };

    canvases.forEach(canvas => {
      const type = canvas.getAttribute('data-snack');
      const sprite = sprites[type];
      if (!sprite) return;
      const ctx = canvas.getContext('2d');
      const pixelSize = canvas.width / 8;

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      for (let row = 0; row < 8; row++) {
        for (let col = 0; col < 8; col++) {
          const char = sprite[row][col];
          const fill = colorMap[char];
          if (fill && fill !== 'transparent') {
            ctx.fillStyle = fill;
            ctx.fillRect(col * pixelSize, row * pixelSize, pixelSize, pixelSize);
          }
        }
      }
    });
  }

  renderPixelArt();
  updateCreditDisplay();
});
